export type ParsedExecuteBoundedTradeInstruction<
  TProgram extends string = typeof BLIND_VAULT_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    vault: TAccountMetas[0];
    strategy: TAccountMetas[1];
    quoteVault: TAccountMetas[2];
    targetVault: TAccountMetas[3];
    demoPool: TAccountMetas[4];
    poolQuoteVault: TAccountMetas[5];
    poolBaseVault: TAccountMetas[6];
    strategist: TAccountMetas[7];
    tokenProgram: TAccountMetas[8];
  };
  data: ExecuteBoundedTradeInstructionData;
};

export function parseExecuteBoundedTradeInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedExecuteBoundedTradeInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 9) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 9,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      vault: getNextAccount(),
      strategy: getNextAccount(),
      quoteVault: getNextAccount(),
      targetVault: getNextAccount(),
      demoPool: getNextAccount(),
      poolQuoteVault: getNextAccount(),
      poolBaseVault: getNextAccount(),
      strategist: getNextAccount(),
      tokenProgram: getNextAccount(),
    },
    data: getExecuteBoundedTradeInstructionDataDecoder().decode(
      instruction.data,
    ),
  };
}
